:root {
  color-scheme: light dark;
  --paper: light-dark(#f7f8fc, #0b1020);
  --surface: light-dark(#fff, #111a2e);
  --ink: light-dark(#131e37, #eff3ff);
  --muted: light-dark(#526079, #b1bdd6);
  --line: light-dark(#dce3ef, #283650);
  --accent: light-dark(#194cb3, #9ab9ff);
  --accent-soft: light-dark(#eaf0ff, #192d54);
  --accent-line: light-dark(#cfddfa, #304b78);
  --control-border: light-dark(#6882b0, #7892c4);
  --control-fill: light-dark(#eef4ff, #172747);
  --control-sheen: light-dark(#fafcff, #22355a);
  --control-hover: light-dark(#dce8ff, #293f6d);
  --control-highlight: light-dark(#ffffffdf, #c9dcff36);
  --action-border: light-dark(#254b9b, #8caeff);
  --action-fill: light-dark(#224ca9, #263e76);
  --action-sheen: light-dark(#335fbd, #395795);
  --action-hover: light-dark(#193c90, #3b5da0);
  --action-ink: #fff;
  --gold: #f6cd82;
  --positive: light-dark(#22644f, #91ddc1);
  --warning: light-dark(#82500b, #f1c179);
  --shadow: light-dark(#1b305515, #0004);
  --display: "Playfair Display", Georgia, serif;
  --body: Inter, system-ui, sans-serif;
}

:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] { color-scheme: dark; }
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--paper); color: var(--ink); font: 400 1rem/1.5 var(--body); }
h1, h2, h3, h4, p { margin: 0; }
a { color: inherit; text-decoration: none; }
button, input, select { font: inherit; }
[hidden] { display: none !important; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
.shell { width: min(1320px, calc(100% - 112px)); margin-inline: auto; }
.icon { display: inline-flex; width: 1em; height: 1em; flex: 0 0 auto; align-items: center; justify-content: center; }
.icon svg { width: 100%; height: 100%; }
.visually-hidden, .skip-link:not(:focus) { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.skip-link { position: fixed; z-index: 3; top: 12px; left: 12px; padding: 12px; border-radius: 8px; background: var(--surface); }

.site-header { border-bottom: 1px solid var(--line); background: var(--surface); }
.header-content, .footer-content { display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.header-content { min-height: 80px; }
.brand { display: inline-flex; align-items: center; gap: 12px; min-width: 0; padding: 5px 9px; line-height: 1.2; }
.school-mark { display: block; flex: none; width: 39px; height: 44px; background: var(--school-mark) center / contain no-repeat; }
.brand strong { display: block; font-size: 1.19rem; font-weight: 700; letter-spacing: -.055em; }
.brand small { display: block; margin-top: 4px; color: var(--muted); font-size: .7rem; }
.main-nav { display: flex; gap: 9px; align-items: center; font-size: .85rem; font-weight: 600; }
.main-nav a { display: flex; align-items: center; justify-content: center; min-height: 44px; padding: 8px 15px; color: var(--accent); text-align: center; }
.header-controls { display: flex; align-items: center; gap: 9px; }
.language-control { display: flex; align-items: center; position: relative; color: var(--muted); }
.language-control > .icon { position: absolute; pointer-events: none; left: 12px; font-size: 1rem; }
.language-control > .language-chevron { left: auto; right: 9px; font-size: .78rem; }
.language-control select, .theme-toggle { height: 44px; color: var(--ink); cursor: pointer; }
.language-control select { appearance: none; padding: 0 29px 0 35px; font-size: .82rem; font-weight: 600; }
.theme-toggle { display: grid; width: 44px; padding: 0; place-items: center; font-size: 1.1rem; }

:is(.brand, .main-nav a, .language-control select, .theme-toggle, .search-box input, .visit-link, .back-to-top) {
  border: 1px solid var(--control-border);
  border-radius: 11px;
  background-color: var(--control-fill);
  background-image: linear-gradient(155deg, var(--control-sheen), transparent 72%);
  box-shadow: inset 0 1px 0 var(--control-highlight), 0 2px 4px var(--shadow);
  transition: background-color .18s, border-color .18s, box-shadow .18s, transform .18s;
}

:is(.main-nav a, .visit-link) {
  --control-border: var(--action-border);
  --control-fill: var(--action-fill);
  --control-sheen: var(--action-sheen);
  --control-hover: var(--action-hover);
  --control-highlight: #dae7ff46;
  color: var(--action-ink);
}

:is(.brand, .main-nav a, .language-control select, .theme-toggle, .search-box input, .visit-link, .back-to-top):focus-visible {
  background-color: var(--control-hover);
}

.hero { position: relative; isolation: isolate; display: grid; align-items: center; overflow: hidden; min-height: 495px; margin-top: 25px; border: 1px solid #ffffff20; border-radius: 26px; color: #fff; background: #101d3c; box-shadow: 0 16px 42px -25px #0717329e; }
.hero-photos, .hero-slide, .hero::after { position: absolute; inset: 0; pointer-events: none; }
.hero-photos { z-index: -2; overflow: hidden; }
.hero-slide {
  background: var(--slide-image) var(--slide-position, 50%) var(--slide-height, 60%) / cover no-repeat;
  opacity: 0;
  transform: translateX(3%);
  transition: opacity .75s ease, transform .75s ease;
}
.hero-slide.is-current { opacity: 1; transform: translateX(0); }
.hero-slide[data-photo="reception"] { --slide-image: var(--photo-reception); --slide-position: 69%; --slide-height: 57%; }
.hero-slide[data-photo="shelves"] { --slide-image: var(--photo-shelves); --slide-position: 63%; --slide-height: 65%; }
.hero-slide[data-photo="lounge"] { --slide-image: var(--photo-lounge); --slide-position: 61%; --slide-height: 62%; }
.hero-slide[data-photo="reading-table"] { --slide-image: var(--photo-reading-table); --slide-position: 59%; --slide-height: 57%; }
.hero-slide[data-photo="study-table"] { --slide-image: var(--photo-study-table); --slide-position: 59%; --slide-height: 56%; }
.hero::after {
  content: "";
  z-index: -1;
  background: linear-gradient(90deg, #0b1731f5 0%, #0b1731e8 27%, #0b1731bf 44%, #0b173128 68%, transparent 100%),
    linear-gradient(0deg, #0b173185, transparent 29%);
}
.hero-content { width: min(780px, 75%); padding: 61px 0 77px clamp(39px, 5.25vw, 83px); }
.hero-controls {
  position: absolute;
  right: 22px;
  bottom: 19px;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px;
  border: 1px solid #a9bce976;
  border-radius: 14px;
  background: #0b1731eb;
  box-shadow: 0 4px 18px #050b1a65;
}
.hero-control {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  padding: 0;
  border: 1px solid #91a9d479;
  border-radius: 9px;
  background: #22395f;
  color: #fff;
  cursor: pointer;
}
.hero-control:hover, .hero-control:focus-visible { background: #355487; }
.hero-control:focus-visible { outline: 2px solid var(--gold); outline-offset: 1px; }
.hero-count { min-width: 44px; text-align: center; font-size: .77rem; font-weight: 600; font-variant-numeric: tabular-nums; }
.eyebrow { display: flex; align-items: center; gap: 9px; margin-bottom: 19px; color: #f3d59f; font-size: .7rem; font-weight: 700; letter-spacing: .17em; text-transform: uppercase; }
.eyebrow .icon { font-size: 1.04rem; }
.hero h1 { font: 600 clamp(3.2rem, 6vw, 6rem)/1.015 var(--display); letter-spacing: -.048em; text-wrap: balance; }
.hero h1 em { display: block; color: var(--gold); font-weight: 500; }
.hero-description { max-width: 440px; margin-top: 22px; color: #e6ecff; font-size: clamp(.95rem, 1.5vw, 1.085rem); line-height: 1.66; text-wrap: pretty; }
.hero-button { display: inline-flex; align-items: center; gap: 15px; margin-top: 28px; padding: 12px 16px 12px 18px; border: 1px solid #ffe3a7; border-radius: 11px; color: #18213b; background: linear-gradient(155deg, #ffe8b2, transparent 76%) var(--gold); box-shadow: inset 0 1px 0 #fff2cf, 0 7px 20px #060c2280; font-size: .88rem; font-weight: 700; transition: background-color .18s, transform .18s; }
.hero-button:focus-visible { outline-color: var(--gold); }

.catalog { padding: 56px 0 80px; scroll-margin-top: 18px; }
.catalog-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding-bottom: 22px; border-bottom: 1px solid var(--line); }
.catalog-toolbar h2 { font: 600 clamp(1.9rem, 3.7vw, 3.1rem)/1.1 var(--display); letter-spacing: -.045em; }
.search-box { position: relative; width: min(100%, 322px); color: var(--muted); }
.search-box > .icon { position: absolute; left: 15px; top: 50%; transform: translateY(-50%); pointer-events: none; }
.search-box input { display: block; width: 100%; min-height: 47px; padding: 9px 14px 9px 42px; color: var(--ink); font-size: .875rem; }
.search-box input::placeholder { color: var(--muted); opacity: 1; }
.collection { margin-top: 34px; scroll-margin-top: 24px; }
.collection + .collection { margin-top: 58px; }
.collection-heading { display: flex; align-items: center; gap: 15px; margin-bottom: 21px; }
.collection-icon { width: 47px; height: 47px; border: 1px solid var(--accent-line); border-radius: 13px; background: var(--accent-soft); color: var(--accent); }
.collection-icon svg { width: 23px; height: 23px; }
.collection h3 { font: 600 clamp(1.45rem, 2.5vw, 2.05rem)/1.15 var(--display); letter-spacing: -.025em; }
.collection-heading p { margin-top: 4px; color: var(--muted); font-size: .86rem; }
.card-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 21px; }
.library-card { position: relative; display: flex; flex-direction: column; min-width: 0; overflow: hidden; border: 1px solid var(--line); border-radius: 17px; background: var(--surface); box-shadow: 0 5px 18px -12px var(--shadow); transition: box-shadow .22s, border-color .22s, transform .22s; }
.library-card:focus-within { outline: 2px solid var(--accent); outline-offset: 3px; }
.card-photo { position: relative; isolation: isolate; display: flex; align-items: flex-start; overflow: hidden; aspect-ratio: 1.78; min-height: 123px; padding: 12px; }
.card-photo::before { content: ""; position: absolute; z-index: -1; inset: 0; background: var(--card-image, linear-gradient(125deg, #456b9d, #172644)) center / cover no-repeat; transition: transform .35s; }
.format-badge { display: inline-flex; align-items: center; gap: 5px; max-width: 100%; padding: 5px 8px; border: 1px solid #ffffff4d; border-radius: 7px; background: #101a30eb; color: #f5f7ff; font-size: .68rem; font-weight: 600; }
.format-badge .icon { font-size: .88rem; }
.card-body { display: flex; flex: 1; flex-direction: column; padding: 16px 16px 13px; }
.card-body h4 { font-size: 1rem; font-weight: 700; line-height: 1.27; letter-spacing: -.025em; text-wrap: pretty; }
.card-description { flex: 1; margin-top: 8px; color: var(--muted); font-size: .81rem; line-height: 1.6; }
.access { display: flex; align-items: baseline; gap: 6px; margin: 13px 0; color: var(--positive); font-size: .71rem; font-weight: 600; }
.access .icon { align-self: center; font-size: .88rem; }
.access--mixed { color: var(--warning); }
.visit-link { display: flex; justify-content: space-between; align-items: center; gap: 6px; min-height: 44px; padding: 6px 10px; color: var(--accent); font-size: .79rem; font-weight: 700; }
.visit-link::after { content: ""; position: absolute; inset: 0; }
.visit-link:focus-visible { outline: none; }
.visit-link .icon { width: 26px; height: 26px; border: 1px solid #ffffff58; border-radius: 8px; background: #ffffff19; }
.visit-link svg { width: 15px; height: 15px; }
.empty-state { padding: 25px 0; color: var(--muted); }

.site-footer { padding-block: 27px; border-top: 1px solid var(--line); background: var(--surface); }
.footer-content .brand strong { font-size: 1rem; }
.footer-content .school-mark { width: 29px; height: 33px; }
.back-to-top { display: inline-flex; align-items: center; gap: 7px; min-height: 44px; padding: 6px 11px; color: var(--accent); font-size: .8rem; font-weight: 600; white-space: nowrap; }

@media (hover: hover) {
  :is(.brand, .main-nav a, .language-control select, .theme-toggle, .search-box input, .back-to-top):hover,
  .library-card:hover .visit-link {
    background-color: var(--control-hover);
    box-shadow: inset 0 1px 0 var(--control-highlight), 0 4px 10px var(--shadow);
  }
  :is(.main-nav a, .theme-toggle, .back-to-top):hover { transform: translateY(-1px); }
  .hero-button:hover { transform: translateY(-2px); background-color: #ffe1a6; }
  .library-card:hover { transform: translateY(-3px); border-color: var(--accent); box-shadow: 0 15px 30px -13px var(--shadow); }
  .library-card:hover .card-photo::before { transform: scale(1.04); }
}

@media (max-width: 1100px) {
  .shell { width: calc(100% - 72px); }
  .card-grid { gap: 14px; }
  .hero { min-height: 445px; }
}
@media (max-width: 960px) {
  .card-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  #uzbek .card-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .header-content { gap: 14px; min-height: 72px; }
}
@media (max-width: 740px) {
  .shell { width: calc(100% - 36px); }
  .header-content { flex-wrap: wrap; gap: 0 8px; padding-top: 11px; }
  .header-content .brand { flex: 1; gap: 8px; padding-inline: 5px; }
  .header-content .brand strong { font-size: 1.06rem; }
  .header-content .brand small { font-size: .63rem; }
  .header-content .school-mark { width: 30px; height: 34px; }
  .header-controls { gap: 6px; }
  .language-control select { padding: 0 21px 0 25px; font-size: .73rem; }
  .language-control > .icon { left: 7px; font-size: .86rem; }
  .language-control > .language-chevron { left: auto; right: 6px; font-size: .69rem; }
  .main-nav { order: 1; width: 100%; justify-content: center; gap: 8px; margin-block: 9px 11px; font-size: .78rem; }
  .main-nav a { flex: 1; padding-inline: 8px; }
  .hero { margin-top: 17px; min-height: 375px; border-radius: 19px; }
  .hero-content { width: 100%; padding: 41px 25px 83px; }
  .hero h1 { font-size: clamp(2.55rem, 8vw, 4.5rem); text-wrap: initial; }
  .hero::after { background: linear-gradient(90deg, #0b1731e8, #0b1731ac 70%, #0b173167), linear-gradient(0deg, #0b1731b3, transparent 45%); }
  .hero-controls { right: 14px; bottom: 12px; }
  .hero-description { margin-top: 16px; }
  .hero-button { margin-top: 23px; }
  .catalog { padding-top: 38px; padding-bottom: 47px; }
  .catalog-toolbar { padding-bottom: 16px; }
  .collection { margin-top: 26px; }
  .collection + .collection { margin-top: 41px; }
  .card-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 465px) {
  .shell { width: calc(100% - 28px); }
  .header-content .brand small { max-width: 145px; }
  .footer-content { gap: 10px; }
  .footer-content .brand { gap: 7px; padding-inline: 5px; }
  .catalog-toolbar { align-items: stretch; flex-direction: column; gap: 13px; }
  .search-box { width: 100%; }
  .card-grid, #uzbek .card-grid { grid-template-columns: minmax(0, 1fr); }
  .card-photo { aspect-ratio: 2.15; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition: none !important; }
  :is(.main-nav a, .theme-toggle, .back-to-top, .hero-button, .library-card):hover,
  .library-card:hover .card-photo::before { transform: none; }
  .hero-slide { transform: none; }
}

@media (pointer: coarse) {
  .hero { touch-action: pan-y pinch-zoom; }
}

