  --photo-headphones: url("data:image/webp;base64,");
  --photo-open-book: url("data:image/webp;base64,");
  --photo-facade: url("data:image/webp;base64,");
  --photo-desk: url("data:image/webp;base64,");
  --photo-globe: url("data:image/webp;base64,");
  --photo-classics: url("data:image/webp;base64,");
  --photo-microphone: url("data:image/webp;base64,");
  --photo-fairytale: url("data:image/webp;base64,");
  --photo-tablet: url("data:image/webp;base64,");
  --photo-african-stories: url("data:image/webp;base64,");
  --photo-archive: url("data:image/webp;base64,");
  --photo-science: url("data:image/webp;base64,");
  --photo-picture-books: url("data:image/webp;base64,");
}
